sp_widget.client_script:
api.controller = function() {

    var c = this;

    /* Filter */
    c.filter = "All";

    /* Pagination */
    c.currentPage = 1;
    c.pageSize = 5;

    c.setFilter = function(status) {

        c.filter = status;
        c.currentPage = 1;

    };

    c.filteredSchedules = function() {

        if (!c.data.schedules)
            return [];

        if (c.filter == "All")
            return c.data.schedules;

        return c.data.schedules.filter(function(item) {
            return item.status == c.filter;
        });

    };

    c.paginatedSchedules = function() {

        var records = c.filteredSchedules();

        var start = (c.currentPage - 1) * c.pageSize;
        var end = start + c.pageSize;

        return records.slice(start, end);

    };

    c.totalPages = function() {

        return Math.max(
            Math.ceil(c.filteredSchedules().length / c.pageSize),
            1
        );

    };

    c.nextPage = function() {

        if (c.currentPage < c.totalPages())
            c.currentPage++;

    };

    c.prevPage = function() {

        if (c.currentPage > 1)
            c.currentPage--;

    };

    /* Mark As Given */

    c.markTaken = function(sysId) {

        c.data.action = "markTaken";
        c.data.sys_id = sysId;

        c.server.update().then(function() {

            c.server.refresh();

        });

    };

};

sp_widget.css:
.tm-schedule-wrapper {
    background: #fff;
    border-radius: 20px;
    padding: 28px;
    margin-top: 24px;
    box-shadow: 0 10px 30px rgba(0,0,0,.08);
}

/* Header */

.schedule-header {
    margin-bottom: 24px;
    border-bottom: 1px solid #e5e7eb;
    padding-bottom: 16px;
}

.schedule-header h2 {
    margin: 0;
    font-size: 22px;
    font-weight: 700;
    color: #0f172a;
}

.schedule-header p {
    margin-top: 6px;
    color: #64748b;
    font-size: 14px;
}

/* Filter Tabs */

.filter-tabs {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    margin-bottom: 24px;
}

.tab-btn {
    border: none;
    background: #f1f5f9;
    color: #475569;
    padding: 10px 18px;
    border-radius: 999px;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: .3s;
}

.tab-btn:hover {
    background: #e2e8f0;
}

.tab-btn.active {
    background: #14b8a6;
    color: #fff;
}

/* Table */

.tm-table {
    width: 100%;
    margin-bottom: 0;
}

.tm-table thead th {
    background: #f8fafc;
    color: #64748b;
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
    padding: 14px;
    border-bottom: 2px solid #e5e7eb;
}

.tm-table td {
    padding: 16px 14px;
    border-bottom: 1px solid #f1f5f9;
    vertical-align: middle;
}

.tm-table tbody tr:hover {
    background: #f8fafc;
}

/* Patient */

.patient-cell {
    display: flex;
    align-items: center;
    gap: 12px;
}

.avatar {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    background: linear-gradient(135deg,#14b8a6,#06b6d4);
    color: #fff;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
}

.patient-name {
    font-weight: 600;
    color: #0f172a;
}

/* Status */

.status-pill {
    min-width: 100px;
    text-align: center;
    padding: 7px 14px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 700;
    display: inline-block;
}

.scheduled {
    background: #dbeafe;
    color: #1d4ed8;
}

.taken {
    background: #dcfce7;
    color: #166534;
}

.nottaken {
    background: #fee2e2;
    color: #991b1b;
}

/* Confirm */

.text-success {
    color: #10b981;
    font-size: 20px;
}

.text-danger {
    color: #ef4444;
    font-size: 20px;
}

/* Button */

.btn-given {
    border: none;
    background: #10b981;
    color: #fff;
    padding: 9px 14px;
    border-radius: 8px;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: .3s;
}

.btn-given:hover {
    background: #059669;
}

.btn-given i {
    margin-right: 5px;
}

/* Labels */

.given-label {
    color: #10b981;
    font-weight: 600;
}

.missed-label {
    color: #ef4444;
    font-weight: 600;
}

/* Empty */

.empty-row {
    text-align: center;
    padding: 30px !important;
    color: #64748b;
}

/* Pagination */

.pagination-wrapper {
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 12px;
    margin-top: 20px;
    padding-top: 18px;
    border-top: 1px solid #e5e7eb;
}

.page-btn {
    border: none;
    background: #14b8a6;
    color: #fff;
    padding: 8px 16px;
    border-radius: 8px;
    cursor: pointer;
    font-weight: 600;
}

.page-btn:hover:not(:disabled) {
    background: #0f766e;
}

.page-btn:disabled {
    opacity: .5;
    cursor: not-allowed;
}

.page-info {
    font-weight: 600;
    color: #475569;
}

/* Responsive */

@media (max-width: 768px) {

    .tm-schedule-wrapper {
        padding: 18px;
    }

    .tm-table {
        min-width: 900px;
    }

    .filter-tabs {
        overflow-x: auto;
        flex-wrap: nowrap;
    }

    .pagination-wrapper {
        justify-content: center;
    }
}

sp_widget.script:
(function() {

    data.schedules = [];

    data.total = 0;
    data.taken = 0;
    data.scheduled = 0;
    data.notTaken = 0;

    var isAdmin = gs.hasRole('admin') ||
                  gs.hasRole('x_snc_trackmed.admin') ||
                  gs.hasRole('x_snc_trackmed.hospital_admin');

    /* Mark As Given */

    if (input && input.action == "markTaken" && input.sys_id) {

        var upd = new GlideRecord('x_snc_trackmed_dose_log');

        if (upd.get(input.sys_id)) {

            // Optional: prevent admins from updating doses
            if (!isAdmin) {
                upd.setValue('status', 'Taken');
                upd.setValue('caregiver_confirmed', true);
                upd.update();
            }
        }
    }

    /* Load Records */

    var gr = new GlideRecord('x_snc_trackmed_dose_log');

    // Caregiver → own records only
    // Admin → all records
    if (!isAdmin) {
        gr.addQuery('care_taker', gs.getUserID());
    }

    gr.orderBy('work_start');
    gr.query();

    while (gr.next()) {

        var patient = gr.getDisplayValue('patient');
        var status = gr.getDisplayValue('status');

        if (status == 'Taken') {
            data.taken++;
        } else if (status == 'Scheduled') {
            data.scheduled++;
        } else if (status == 'Not Taken') {
            data.notTaken++;
        }

        data.total++;

        data.schedules.push({

            sys_id: gr.getUniqueValue(),

            patient: patient,

            medication: gr.getDisplayValue('medication'),

            caregiver: gr.getDisplayValue('care_taker'),

            work_start: gr.getDisplayValue('work_start'),

            status: status,

            confirmed: gr.caregiver_confirmed == true,

            initial: patient ?
                patient.substring(0, 1).toUpperCase() : ''

        });
    }

    data.isAdmin = isAdmin;

})();
